<!doctype html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}" dir="{{ app()->getLocale() === 'ar' ? 'rtl' : 'ltr' }}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $policy->printTitle() }} {{ $return->return_number ?: '#'.$return->id }}</title><style>body{font-family:Arial,sans-serif;color:#111827;margin:2rem}.toolbar{display:flex;justify-content:space-between;margin-bottom:2rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin:1.5rem 0}.muted{color:#6b7280;font-size:.85rem}table{width:100%;border-collapse:collapse;margin-top:1.5rem}th,td{border-bottom:1px solid #d1d5db;padding:.6rem;text-align:start}.no-print{display:block}@media print{.no-print{display:none}body{margin:0}}</style></head>
<body><div class="toolbar no-print"><a href="{{ route('purchasing.returns.show', $return) }}">{{ __('Back to detail') }}</a><button onclick="window.print()">{{ __('Print') }}</button></div><h1>{{ $policy->printTitle() }}</h1><p class="muted">{{ $return->return_number ?: '#'.$return->id }} · {{ $return->status }}</p><div class="grid"><div><strong>{{ __('Supplier') }}</strong><br>{{ $return->supplier?->name_en ?: $return->supplier?->name_ar }}</div><div><strong>{{ __('Store') }}</strong><br>{{ $return->store?->name }}</div><div><strong>{{ __('Original invoice') }}</strong><br>{{ $return->purchaseInvoice?->invoice_number }}</div><div><strong>{{ __('Reason') }}</strong><br>{{ $return->reason?->code }} — {{ $return->reason?->label_en }}</div><div><strong>{{ __('Created by') }}</strong><br>{{ $return->creator?->name }}</div><div><strong>{{ __('Approved by') }}</strong><br>{{ $return->approver?->name ?: '—' }}</div></div><table><thead><tr><th>{{ __('Product') }}</th><th>{{ __('Quantity') }}</th><th>{{ __('Original unit cost') }}</th><th>{{ __('Total cost') }}</th></tr></thead><tbody>@foreach($return->lines as $line)<tr><td>{{ $line->product?->name_en ?: $line->product?->name_ar ?: '#'.$line->product_id }}</td><td>{{ $line->quantity }}</td><td>{{ $line->unit_cost }}</td><td>{{ $line->total_cost }}</td></tr>@endforeach</tbody></table><p><strong>{{ __('Total cost') }}:</strong> {{ $return->total_amount }}</p><p class="muted">{{ $policy->printFooter() }}</p></body></html>
